// ======================================================
// INSIGHTFLOW AI V2
// DYNAMIC DATASET PROFILER
// Works with ANY CSV dataset
// ======================================================

const rows = $input.all().map(item => item.json);

if (!rows.length) {
  throw new Error("No CSV rows were received.");
}

// ======================================================
// BASIC DATASET INFORMATION
// ======================================================

const totalRows = rows.length;

const columns = [
  ...new Set(
    rows.flatMap(row => Object.keys(row))
  )
];

// ======================================================
// HELPER FUNCTIONS
// ======================================================

function isEmpty(value) {
  return (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  );
}

function toNumber(value) {

  if (isEmpty(value)) {
    return null;
  }

  const cleaned = String(value)
    .replace(/,/g, "")
    .replace(/₹/g, "")
    .replace(/\$/g, "")
    .replace(/%/g, "")
    .trim();

  const number = Number(cleaned);

  return Number.isFinite(number)
    ? number
    : null;
}

function looksLikeDate(value) {

  if (isEmpty(value)) {
    return false;
  }

  const text = String(value).trim();

  // Avoid treating simple numbers as dates
  if (/^\d+$/.test(text)) {
    return false;
  }

  // Common date patterns
  const datePattern =
    /^\d{4}[-/]\d{1,2}[-/]\d{1,2}$/;

  const datePattern2 =
    /^\d{1,2}[-/]\d{1,2}[-/]\d{4}$/;

  if (
    datePattern.test(text) ||
    datePattern2.test(text)
  ) {
    const date = new Date(text);

    return !isNaN(date.getTime());
  }

  return false;
}

// ======================================================
// COLUMN CLASSIFICATION
// ======================================================

const numericColumns = [];
const categoricalColumns = [];
const dateColumns = [];

const columnProfiles = {};

for (const column of columns) {

  const values = rows
    .map(row => row[column])
    .filter(value => !isEmpty(value));

  const numericValues = values
    .map(value => toNumber(value))
    .filter(value => value !== null);

  const dateValues = values
    .filter(value => looksLikeDate(value));

  const uniqueValues = [
    ...new Set(
      values.map(value => String(value).trim())
    )
  ];

  const numericRatio =
    values.length
      ? numericValues.length / values.length
      : 0;

  const dateRatio =
    values.length
      ? dateValues.length / values.length
      : 0;

  let type = "categorical";

  if (dateRatio >= 0.8) {

    type = "date";
    dateColumns.push(column);

  } else if (numericRatio >= 0.8) {

    type = "numeric";
    numericColumns.push(column);

  } else {

    type = "categorical";
    categoricalColumns.push(column);
  }

  columnProfiles[column] = {
    type,
    total_values: values.length,
    missing_values:
      totalRows - values.length,
    unique_values:
      uniqueValues.length
  };
}

// ======================================================
// DATA QUALITY
// ======================================================

// Missing values

let totalMissingValues = 0;

for (const column of columns) {

  for (const row of rows) {

    if (isEmpty(row[column])) {
      totalMissingValues++;
    }
  }
}

// Duplicate rows

const rowHashes = new Set();

let duplicateRows = 0;

for (const row of rows) {

  const hash = JSON.stringify(
    columns.map(column => row[column] ?? null)
  );

  if (rowHashes.has(hash)) {
    duplicateRows++;
  } else {
    rowHashes.add(hash);
  }
}

// ======================================================
// NUMERIC ANALYSIS
// ======================================================

const numericAnalysis = {};

for (const column of numericColumns) {

  const values = rows
    .map(row => toNumber(row[column]))
    .filter(value => value !== null);

  if (!values.length) {
    continue;
  }

  const sum = values.reduce(
    (a, b) => a + b,
    0
  );

  const average =
    sum / values.length;

  numericAnalysis[column] = {
    count: values.length,
    sum: Number(sum.toFixed(2)),
    average: Number(average.toFixed(2)),
    minimum: Math.min(...values),
    maximum: Math.max(...values)
  };
}

// ======================================================
// CATEGORICAL ANALYSIS
// ======================================================

const categoricalAnalysis = {};

for (const column of categoricalColumns) {

  const counts = {};

  for (const row of rows) {

    const value = row[column];

    if (isEmpty(value)) {
      continue;
    }

    const key = String(value).trim();

    counts[key] =
      (counts[key] || 0) + 1;
  }

  const topValues =
    Object.entries(counts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([value, count]) => ({
        value,
        count
      }));

  categoricalAnalysis[column] = {
    unique_values:
      Object.keys(counts).length,

    top_values:
      topValues
  };
}

// ======================================================
// DATE ANALYSIS
// ======================================================

const dateAnalysis = {};

for (const column of dateColumns) {

  const dates = rows
    .map(row => row[column])
    .filter(value => looksLikeDate(value))
    .map(value => new Date(value))
    .filter(date => !isNaN(date.getTime()));

  if (!dates.length) {
    continue;
  }

  const timestamps =
    dates.map(date => date.getTime());

  const earliest =
    new Date(Math.min(...timestamps));

  const latest =
    new Date(Math.max(...timestamps));

  dateAnalysis[column] = {

    count: dates.length,

    earliest:
      earliest.toISOString(),

    latest:
      latest.toISOString()
  };
}

// ======================================================
// DATASET TYPE DETECTION
// ======================================================

const columnText =
  columns
    .join(" ")
    .toLowerCase();

let datasetType =
  "General Business Dataset";

if (
  columnText.includes("subscriber") ||
  columnText.includes("subscription") ||
  columnText.includes("membership")
) {

  datasetType =
    "Subscriber / Subscription Dataset";

} else if (
  columnText.includes("employee") ||
  columnText.includes("salary") ||
  columnText.includes("department") ||
  columnText.includes("job_title")
) {

  datasetType =
    "Employee / HR Dataset";

} else if (
  columnText.includes("order") ||
  columnText.includes("sales") ||
  columnText.includes("revenue") ||
  columnText.includes("invoice")
) {

  datasetType =
    "Sales / Business Dataset";

} else if (
  columnText.includes("student") ||
  columnText.includes("marks") ||
  columnText.includes("grade") ||
  columnText.includes("course")
) {

  datasetType =
    "Education Dataset";

} else if (
  columnText.includes("review") ||
  columnText.includes("rating") ||
  columnText.includes("sentiment")
) {

  datasetType =
    "Review / Customer Feedback Dataset";
}

// ======================================================
// QUALITY STATUS
// ======================================================

let qualityStatus = "GOOD";

if (
  totalMissingValues > 0 ||
  duplicateRows > 0
) {

  qualityStatus =
    "REVIEW_REQUIRED";
}

// ======================================================
// FINAL PROFILE
// ======================================================

const datasetProfile = {

  dataset_type:
    datasetType,

  dataset_size: {

    rows:
      totalRows,

    columns:
      columns.length
  },

  columns,

  column_types: {

    numeric:
      numericColumns,

    categorical:
      categoricalColumns,

    date:
      dateColumns
  },

  column_profiles:
    columnProfiles,

  data_quality: {

    duplicate_rows:
      duplicateRows,

    total_missing_values:
      totalMissingValues,

    quality_status:
      qualityStatus
  },

  numeric_analysis:
    numericAnalysis,

  categorical_analysis:
    categoricalAnalysis,

  date_analysis:
    dateAnalysis
};

// ======================================================
// OUTPUT
// ======================================================

return [

  {

    json: {

      report_date:
        "21 August 2026",

      report_status:
        "SUCCESS",

      dataset_profile:
        datasetProfile

    }

  }

];

// ============================================================
// INSIGHTFLOW AI
// DYNAMIC KPI ENGINE V2
// UNIVERSAL CSV DATASET ANALYSIS
// ============================================================
//
// IMPORTANT:
// This node must work with ANY CSV dataset.
// It must NOT assume subscribers, HR, students, sales, etc.
// ============================================================


// ============================================================
// 1. INPUT
// ============================================================

const input = $input.first().json;

const profile = input.dataset_profile;
const rows = input.dataset_rows || [];

if (!profile) {
  throw new Error(
    "Dataset profile not found. Connect the Dataset Profiler before this node."
  );
}


// ============================================================
// 2. BASIC DATASET INFORMATION
// ============================================================

const columns = Array.isArray(profile.columns)
  ? profile.columns
  : [];

const totalRows = rows.length;

const numericColumns =
  profile.column_types?.numeric || [];

const categoricalColumns =
  profile.column_types?.categorical || [];

const dateColumns =
  profile.column_types?.date || [];


// ============================================================
// 3. DATA QUALITY
// ============================================================

const duplicateRows =
  Number(profile.data_quality?.duplicate_rows || 0);

const totalMissingValues =
  Number(profile.data_quality?.total_missing_values || 0);

const qualityStatus =
  profile.data_quality?.quality_status ||
  "UNKNOWN";


// ============================================================
// 4. HELPER FUNCTIONS
// ============================================================

function cleanNumber(value) {

  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return null;
  }

  const cleaned = String(value)
    .replace(/,/g, "")
    .replace(/₹/g, "")
    .replace(/\$/g, "")
    .replace(/€/g, "")
    .replace(/£/g, "")
    .replace(/%/g, "")
    .trim();

  const number = Number(cleaned);

  return Number.isFinite(number)
    ? number
    : null;
}


function normalizeColumnName(column) {

  return String(column)
    .toLowerCase()
    .trim()
    .replace(/\s+/g, "_");
}


function findColumn(keywords, availableColumns) {

  const normalized = availableColumns.map(column => ({
    original: column,
    normalized: normalizeColumnName(column)
  }));

  for (const keyword of keywords) {

    const normalizedKeyword =
      normalizeColumnName(keyword);

    const exactMatch = normalized.find(
      column =>
        column.normalized === normalizedKeyword
    );

    if (exactMatch) {
      return exactMatch.original;
    }
  }

  for (const keyword of keywords) {

    const normalizedKeyword =
      normalizeColumnName(keyword);

    const partialMatch = normalized.find(
      column =>
        column.normalized.includes(normalizedKeyword)
    );

    if (partialMatch) {
      return partialMatch.original;
    }
  }

  return null;
}


// ============================================================
// 5. NUMERIC KPI ANALYSIS
// ============================================================

const numericKPIs = {};

for (const column of numericColumns) {

  const values = rows
    .map(row => cleanNumber(row[column]))
    .filter(value => value !== null);

  if (values.length === 0) {
    continue;
  }

  const sum = values.reduce(
    (total, value) => total + value,
    0
  );

  const average =
    sum / values.length;

  const minimum =
    Math.min(...values);

  const maximum =
    Math.max(...values);

  numericKPIs[column] = {

    count: values.length,

    sum: Number(
      sum.toFixed(2)
    ),

    average: Number(
      average.toFixed(2)
    ),

    minimum,

    maximum

  };
}


// ============================================================
// 6. CATEGORICAL KPI ANALYSIS
// ============================================================

const categoricalKPIs = {};

for (const column of categoricalColumns) {

  const counts = {};

  for (const row of rows) {

    const rawValue = row[column];

    if (
      rawValue === null ||
      rawValue === undefined ||
      String(rawValue).trim() === ""
    ) {
      continue;
    }

    const value =
      String(rawValue).trim();

    counts[value] =
      (counts[value] || 0) + 1;
  }

  const sorted =
    Object.entries(counts)
      .sort((a, b) => b[1] - a[1]);

  categoricalKPIs[column] = {

    unique_values:
      sorted.length,

    top_values:
      sorted
        .slice(0, 10)
        .map(([value, count]) => ({
          value,
          count
        }))
  };
}


// ============================================================
// 7. DATE KPI ANALYSIS
// ============================================================

const dateKPIs = {};

for (const column of dateColumns) {

  const validDates = rows
    .map(row => row[column])
    .filter(value =>
      value !== null &&
      value !== undefined &&
      String(value).trim() !== ""
    )
    .map(value => new Date(value))
    .filter(date =>
      !isNaN(date.getTime())
    );

  if (validDates.length === 0) {
    continue;
  }

  const timestamps =
    validDates.map(
      date => date.getTime()
    );

  const earliest =
    new Date(
      Math.min(...timestamps)
    );

  const latest =
    new Date(
      Math.max(...timestamps)
    );

  dateKPIs[column] = {

    count:
      validDates.length,

    earliest:
      earliest.toISOString(),

    latest:
      latest.toISOString()

  };
}


// ============================================================
// 8. AUTOMATIC COLUMN ROLE DETECTION
// ============================================================

const detectedColumns = {

  id: findColumn(
    [
      "id",
      "customer_id",
      "subscriber_id",
      "user_id",
      "employee_id",
      "student_id",
      "order_id",
      "transaction_id",
      "product_id"
    ],
    columns
  ),

  name: findColumn(
    [
      "name",
      "customer_name",
      "employee_name",
      "student_name",
      "product_name"
    ],
    columns
  ),

  status: findColumn(
    [
      "status",
      "subscription_status",
      "employment_status",
      "order_status",
      "student_status",
      "state_status",
      "condition"
    ],
    categoricalColumns
  ),

  revenue: findColumn(
    [
      "revenue",
      "sales",
      "sales_amount",
      "amount",
      "price",
      "income",
      "profit",
      "salary",
      "monthly_fee",
      "mrr"
    ],
    numericColumns
  ),

  quantity: findColumn(
    [
      "quantity",
      "qty",
      "units",
      "count"
    ],
    numericColumns
  ),

  age: findColumn(
    [
      "age"
    ],
    numericColumns
  ),

  gender: findColumn(
    [
      "gender",
      "sex"
    ],
    categoricalColumns
  ),

  category: findColumn(
    [
      "category",
      "type",
      "segment",
      "class",
      "department"
    ],
    categoricalColumns
  ),

  plan: findColumn(
    [
      "plan",
      "subscription_plan",
      "subscription",
      "package",
      "tier"
    ],
    categoricalColumns
  ),

  country: findColumn(
    [
      "country"
    ],
    categoricalColumns
  ),

  state: findColumn(
    [
      "state",
      "province",
      "region"
    ],
    categoricalColumns
  ),

  city: findColumn(
    [
      "city"
    ],
    categoricalColumns
  ),

  date: findColumn(
    [
      "date",
      "order_date",
      "transaction_date",
      "signup_date",
      "created_at",
      "hire_date",
      "joining_date"
    ],
    [
      ...dateColumns,
      ...columns
    ]
  )
};


// ============================================================
// 9. DYNAMIC DATASET TYPE DETECTION
// ============================================================
//
// IMPORTANT:
// We use multiple column signatures instead of one keyword.
// This prevents a random column from incorrectly classifying
// the dataset.
// ============================================================

const columnText =
  columns
    .map(column =>
      normalizeColumnName(column)
    )
    .join(" ");

const signatures = {

  subscriber: [
    "subscriber_id",
    "subscription_status",
    "subscription_plan",
    "monthly_fee",
    "subscriber"
  ],

  employee: [
    "employee_id",
    "employee_name",
    "salary",
    "department",
    "job_title",
    "hire_date",
    "joining_date",
    "employment_status"
  ],

  student: [
    "student_id",
    "student_name",
    "marks",
    "grade",
    "gpa",
    "percentage",
    "attendance",
    "course",
    "subject",
    "semester",
    "academic"
  ],

  sales: [
    "order_id",
    "order_date",
    "sales_amount",
    "sales",
    "revenue",
    "profit",
    "product_id",
    "quantity"
  ],

  finance: [
    "transaction_id",
    "transaction_date",
    "amount",
    "balance",
    "debit",
    "credit",
    "expense",
    "income"
  ],

  ecommerce: [
    "product_id",
    "product_name",
    "order_id",
    "quantity",
    "price",
    "category",
    "order_date"
  ],

  marketing: [
    "campaign_id",
    "campaign_name",
    "impressions",
    "clicks",
    "conversions",
    "conversion_rate",
    "campaign"
  ],

  healthcare: [
    "patient_id",
    "patient_name",
    "diagnosis",
    "treatment",
    "doctor",
    "medical"
  ],

  reviews: [
    "review_id",
    "review_text",
    "rating",
    "review",
    "sentiment"
  ]
};


function scoreSignature(keywords) {

  let score = 0;

  for (const keyword of keywords) {

    const normalizedKeyword =
      normalizeColumnName(keyword);

    if (
      columnText.includes(
        normalizedKeyword
      )
    ) {
      score++;
    }
  }

  return score;
}


const datasetScores = {

  "Subscriber / Subscription Dataset":
    scoreSignature(
      signatures.subscriber
    ),

  "Employee / HR Dataset":
    scoreSignature(
      signatures.employee
    ),

  "Student / Education Dataset":
    scoreSignature(
      signatures.student
    ),

  "Sales / Business Dataset":
    scoreSignature(
      signatures.sales
    ),

  "Finance / Transaction Dataset":
    scoreSignature(
      signatures.finance
    ),

  "E-commerce Dataset":
    scoreSignature(
      signatures.ecommerce
    ),

  "Marketing / Campaign Dataset":
    scoreSignature(
      signatures.marketing
    ),

  "Healthcare Dataset":
    scoreSignature(
      signatures.healthcare
    ),

  "Reviews / Feedback Dataset":
    scoreSignature(
      signatures.reviews
    )
};


// ============================================================
// 10. SELECT BEST DATASET TYPE
// ============================================================

let datasetType =
  "General / Mixed Dataset";

let highestScore = 0;

for (
  const [type, score]
  of Object.entries(datasetScores)
) {

  if (score > highestScore) {

    highestScore = score;

    datasetType = type;
  }
}


// Require at least 2 matching signature columns.
// Otherwise keep General / Mixed Dataset.

if (highestScore < 2) {

  datasetType =
    "General / Mixed Dataset";
}


// ============================================================
// 11. DATASET PROFILE SUMMARY
// ============================================================

const dynamicKPIs = {

  dataset_type:
    datasetType,

  dataset_type_confidence:
    highestScore >= 4
      ? "HIGH"
      : highestScore >= 2
        ? "MEDIUM"
        : "LOW",

  dataset_size: {

    rows:
      totalRows,

    columns:
      columns.length

  },

  data_quality: {

    duplicate_rows:
      duplicateRows,

    total_missing_values:
      totalMissingValues,

    quality_status:
      qualityStatus

  },

  detected_columns:
    detectedColumns,

  numeric_kpis:
    numericKPIs,

  categorical_kpis:
    categoricalKPIs,

  date_kpis:
    dateKPIs,

  dataset_type_scores:
    datasetScores,

  available_columns: {

    numeric:
      numericColumns,

    categorical:
      categoricalColumns,

    date:
      dateColumns

  }

};


// ============================================================
// 12. FINAL OUTPUT
// ============================================================

return [

  {

    json: {

      report_date:
        input.report_date ||
        "21 August 2026",

      report_status:
        "SUCCESS",

      dataset_type:
        datasetType,

      dynamic_kpis:
        dynamicKPIs,

      dataset_profile:
        profile

    }

  }

];

// ============================================================
// DYNAMIC REPORT FORMATTER
// UNIVERSAL GEMINI RESPONSE EXTRACTOR
// ============================================================

const input = $input.first().json;

let report = "";


// ============================================================
// CASE 1 — Gemini content.parts[].text
// ============================================================

if (
  input.content &&
  Array.isArray(input.content.parts)
) {

  for (const part of input.content.parts) {

    if (
      part &&
      typeof part.text === "string"
    ) {

      const text = part.text.trim();

      // Ignore thinking/reasoning.
      // Look for the actual report.
      if (
        text.includes("EXECUTIVE SUMMARY") &&
        text.includes("KEY FINDINGS")
      ) {

        report = text;
        break;

      }

    }

  }

}


// ============================================================
// CASE 2 — Direct text field
// ============================================================

if (
  !report &&
  typeof input.text === "string"
) {

  const text = input.text.trim();

  if (
    text.includes("EXECUTIVE SUMMARY") &&
    text.includes("KEY FINDINGS")
  ) {

    report = text;

  }

}


// ============================================================
// CASE 3 — candidates[].content.parts[].text
// ============================================================

if (
  !report &&
  Array.isArray(input.candidates)
) {

  for (const candidate of input.candidates) {

    const parts =
      candidate?.content?.parts;

    if (!Array.isArray(parts)) {
      continue;
    }

    for (const part of parts) {

      if (
        part &&
        typeof part.text === "string"
      ) {

        const text =
          part.text.trim();

        if (
          text.includes("EXECUTIVE SUMMARY") &&
          text.includes("KEY FINDINGS")
        ) {

          report = text;
          break;

        }

      }

    }

    if (report) {
      break;
    }

  }

}


// ============================================================
// VALIDATION
// ============================================================

if (!report) {

  throw new Error(
    "No management report found in Gemini response. " +
    "Open Message a model and verify its output."
  );

}


// ============================================================
// OUTPUT
// ============================================================

return [
  {
    json: {

      report_date:
        "21 August 2026",

      report_status:
        "SUCCESS",

      report_title:
        "Dynamic Business Analytics Report",

      ai_business_report:
        report,

      formatted_report:
        report

    }
  }
];

// ============================================================
// FINAL PORTFOLIO REPORT
// UNIVERSAL DATASET VERSION
// ============================================================

const input = $input.first().json;

const report =
  input.formatted_report ||
  input.ai_business_report;

if (!report) {
  throw new Error(
    "No formatted report received from Dynamic Report Formatter."
  );
}

return [
  {
    json: {

      report_date:
        input.report_date || "21 August 2026",

      report_status:
        "SUCCESS",

      report_title:
        input.report_title ||
        "Dynamic Business Analytics Report",

      ai_business_report:
        report,

      formatted_report:
        report

    }
  }
];

