(() => {

  const report =
    $json.report ||
    $json.formatted_report ||
    $json.ai_business_report ||
    "";

  if (!report) {
    return `
      <div style="font-family:Arial,sans-serif;padding:30px;">
        <h2 style="color:#b91c1c;">Report Not Available</h2>
        <p>The workflow did not provide a generated report.</p>
      </div>
    `;
  }

  // --------------------------------------------------
  // ESCAPE HTML
  // --------------------------------------------------

  let html = report
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

  // --------------------------------------------------
  // MARKDOWN FORMATTING
  // --------------------------------------------------

  // Bold
  html = html.replace(
    /\*\*(.*?)\*\*/g,
    "<strong>$1</strong>"
  );

  // H1
  html = html.replace(
    /^# (.+)$/gm,
    `<h1 style="
      margin:0 0 18px;
      font-size:26px;
      color:#111827;
    ">$1</h1>`
  );

  // H2
  html = html.replace(
    /^## (.+)$/gm,
    `<h2 style="
      margin:28px 0 12px;
      padding-bottom:8px;
      border-bottom:1px solid #e5e7eb;
      font-size:20px;
      color:#111827;
    ">$1</h2>`
  );

  // H3
  html = html.replace(
    /^### (.+)$/gm,
    `<h3 style="
      margin:20px 0 8px;
      font-size:17px;
      color:#374151;
    ">$1</h3>`
  );

  // --------------------------------------------------
  // SECTION HEADINGS WITHOUT MARKDOWN
  // --------------------------------------------------

  const sections = [
    "DATE",
    "EXECUTIVE SUMMARY",
    "KEY FINDINGS",
    "DATASET & DATA QUALITY ANALYSIS",
    "CUSTOMER / ENTITY ANALYSIS",
    "PRODUCT / CATEGORY ANALYSIS",
    "SUBSCRIPTION / PRODUCT / CATEGORY ANALYSIS",
    "FINANCIAL / NUMERIC ANALYSIS",
    "REVENUE / FINANCIAL ANALYSIS",
    "GEOGRAPHIC ANALYSIS",
    "RISKS",
    "OPPORTUNITIES",
    "RECOMMENDATIONS",
    "MANAGEMENT QUESTIONS"
  ];

  for (const section of sections) {

    const escapedSection =
      section.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

    html = html.replace(
      new RegExp(
        `^${escapedSection}$`,
        "gm"
      ),
      `<h2 style="
        margin:30px 0 12px;
        padding:10px 14px;
        background:#f3f4f6;
        border-left:4px solid #111827;
        font-size:19px;
        color:#111827;
      ">${section}</h2>`
    );
  }

  // --------------------------------------------------
  // NUMBERED LISTS
  // --------------------------------------------------

  html = html.replace(
    /^\s*(\d+)\.\s+(.+)$/gm,
    `<div style="
      margin:8px 0;
      padding:10px 12px;
      background:#f9fafb;
      border-radius:6px;
      line-height:1.6;
    ">
      <strong>$1.</strong> $2
    </div>`
  );

  // --------------------------------------------------
  // BULLET LISTS
  // --------------------------------------------------

  html = html.replace(
    /^\s*[-*]\s+(.+)$/gm,
    `<div style="
      margin:6px 0;
      padding-left:12px;
      line-height:1.6;
    ">
      • $1
    </div>`
  );

  // --------------------------------------------------
  // HORIZONTAL RULE
  // --------------------------------------------------

  html = html.replace(
    /^---$/gm,
    `<hr style="
      border:0;
      border-top:1px solid #e5e7eb;
      margin:24px 0;
    ">`
  );

  // --------------------------------------------------
  // LINE BREAKS
  // --------------------------------------------------

  html = html.replace(/\n/g, "<br>");

  // --------------------------------------------------
  // FINAL EMAIL
  // --------------------------------------------------

  return `

  <div style="
    margin:0;
    padding:30px 15px;
    background:#f3f4f6;
    font-family:Arial,Helvetica,sans-serif;
