        ">
          Dynamic Management Report
        </div>

        <div style="
          margin-top:8px;
          font-size:14px;
          opacity:0.8;
        ">
          Automatically generated from the uploaded CSV dataset
        </div>

      </div>

      <!-- REPORT BODY -->

      <div style="
        padding:30px 34px;
        font-size:14px;
        line-height:1.7;
      ">

        ${html}

      </div>

      <!-- FOOTER -->

      <div style="
        border-top:1px solid #e5e7eb;
        padding:18px 30px;
        background:#f9fafb;
        text-align:center;
        font-size:12px;
