// ============================================
// REPORT VALIDATION
// ============================================

const input = $input.first().json;

const report =
  input.formatted_report ||
  input.ai_business_report ||
  "";

if (!report || typeof report !== "string") {
  throw new Error("No formatted AI report received.");
}

const requiredSections = [
  "DATE",
  "EXECUTIVE SUMMARY",
  "KEY FINDINGS",
  "RISKS",
  "RECOMMENDATIONS",
  "MANAGEMENT QUESTIONS"
];

const missingSections = requiredSections.filter(
  section => !report.toUpperCase().includes(section)
);

if (missingSections.length > 0) {
  throw new Error(
    `Report validation failed. Missing sections: ${missingSections.join(", ")}`
  );
}

// Check report date
const expectedDate = "21 August 2026";

if (!report.includes(`DATE: ${expectedDate}`)) {
  throw new Error(
    `Report validation failed. Expected report date: ${expectedDate}`
  );
}

// Basic quality checks
if (report.length < 500) {
  throw new Error(
    "Report validation failed. AI report is too short."
  );
}

// ============================================
// SUCCESS
// ============================================

return [
  {
    json: {
      report_date: expectedDate,
      report_status: "VALIDATED",
      report_title: "Dynamic Business Analytics Report",

      validation: {
        status: "PASS",
        missing_sections: [],
        report_length: report.length
      },

      formatted_report: report,
      ai_business_report: report
    }
  }
];

// ============================================
// REPORT EXECUTION LOG
// ============================================

const input = $input.first().json;

const report = input.formatted_report || "";

return [
  {
    json: {
      report_date: input.report_date || "21 August 2026",

      execution_status: "SUCCESS",

      report_title:
        input.report_title ||
        "Dynamic Business Analytics Report",

      report_generated: true,

      report_length: report.length,

      validation_status:
        input.validation?.status || "PASS",

      execution_timestamp:
        new Date().toISOString(),

      formatted_report: report,

      ai_business_report: report
    }
  }
];

// ============================================
// FINAL REPORT OUTPUT
// ============================================

const input = $input.first().json;

const report = input.formatted_report || "";

if (!report) {
  throw new Error("Final report is empty.");
}

return [
  {
    json: {
      report_date: input.report_date,

      report_status: "SUCCESS",

      report_title:
        input.report_title ||
        "Dynamic Business Analytics Report",

      execution_status:
        input.execution_status || "SUCCESS",

      validation_status:
        input.validation_status || "PASS",

      report_length:
        input.report_length || report.length,

      execution_timestamp:
        input.execution_timestamp || new Date().toISOString(),

      report: report
    }
  }
];
